"""Migration of legacy ACCT_MASTER validation rules from Meridian CRM 4.2."""

from decimal import Decimal
from typing import Any


def _value(row: dict, column: str) -> Any:
    """Return legacy-style empty value for missing or null fields."""
    value = row.get(column, "")
    return "" if value is None else value


def _length(value: Any) -> int:
    """Legacy LEN: missing/empty values have length zero."""
    if value is None:
        return 0
    return len(str(value))


def _nvl(value: Any, default: Any) -> Any:
    """Legacy NVL: empty, missing, and null values use the default."""
    return default if value is None or value == "" else value


def _numeric(value: Any) -> Decimal:
    """Apply legacy numeric coercion, including empty values becoming zero."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """
    Validate an ACCT_MASTER post-write image in legacy rule-file order.

    The injected ``today`` parameter is retained for the fixed interface; none
    of the migrated rules references TODAY().
    """
    del today
    errors: list[dict] = []

    def fail(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    # ACC-001: WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if _length(_value(record, "ACCT_NM")) < 2:
            fail("E1001", "Account name too short")

    # ACC-002: WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        acct_typ = _value(record, "ACCT_TYP")
        if not (
            acct_typ == "C"
            or acct_typ == "P"
            or acct_typ == "R"
            or acct_typ == "X"
        ):
            fail("E1002", "Invalid account type")

    # ACC-003: WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        ann_rev = _numeric(_nvl(_value(record, "ANN_REV"), 0))
        if ann_rev < Decimal(0):
            fail("E1003", "Annual revenue negative")

    # ACC-004: WHEN UPDATE
    if event == "UPDATE":
        old_record = old if old is not None else {}
        old_cred_hold = _value(old_record, "CRED_HOLD")
        cred_hold = _value(record, "CRED_HOLD")
        cred_limit = _numeric(_value(record, "CRED_LIMIT"))
        if old_cred_hold == "Y" and cred_hold == "N" and cred_limit <= Decimal(0):
            fail("E1004", "Cannot release credit hold with zero credit limit")

    # ACC-005: WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if _length(_value(record, "REGION_CD")) != 3:
            fail("E1005", "Region code must be 3 chars", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected legacy validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
